        // accessor's PDB sequence points, reported against the owning property (#3278).
        var (exit, output, error) = await RunAppAsync(
            "member", "JsonSerializerOptions", "--platform", "System.Text.Json",
            "MaxDepth", "-S", "Source Locations", "--tips", "q");

        Assert.Equal(0, exit);
