            var discovery = await RunAppAsync(
                "library", TestAssemblyPath, "-D", "",
                "--count", "--rows", "1", "--tips", "q");
            var renderedTfms = await RunAppAsync(
                "package", packagePath, "--tfms",
                "--jsonl", "--rows", "1", "--tips", "q");
            var renderedDiscovery = await RunAppAsync(
                "library", TestAssemblyPath, "-D", "",
