            Assert.Equal("", emptyDocument.RootElement.GetProperty("name").GetString());
            Assert.Equal("", emptyDocument.RootElement.GetProperty("description").GetString());
        }
        finally
        {
            Directory.Delete(tempDir, recursive: true);
        }
    }

