                "--count",
                "--skip-empty");
            var tail = await RunAppAsync(
                "package",
                withReadme,
                withoutReadme,
                "-S",
                "Package README file",
                "--columns",
                "Path",
                "--rows",
                "1",
                "--tail",
                "--tsv");
            var tailWithoutHeader = await RunAppAsync(
                "package",
                withReadme,
                withoutReadme,
